<script setup lang="ts">
import type {DecorationPage,DecorationHeader,DecorationRoute} from '../../../../api/src/core/decoration-types'
import {decorationHeader} from '../../../../api/src/core/decoration-contract.mjs'
import ConsoleDialog from './ConsoleDialog.vue'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import DecorationHeaderPreview from './DecorationHeaderPreview.vue'
import DecorationColorField from './DecorationColorField.vue'
import ConsolePagePathPicker from './ConsolePagePathPicker.vue'
import ImageSelectTile from './ImageSelectTile.vue'
import MaterialPicker from './MaterialPicker.vue'
const props=defineProps<{disabled?:boolean;imageUrl:(id:string)=>string;materialEndpoint:string;routes:DecorationRoute[]}>()
const page=defineModel<DecorationPage>({required:true})
const header=computed(()=>decorationHeader(page.value)),open=ref(false),picker=ref(false),selected=ref<DecorationHeader['mode']>('title')
const styles=[{value:'title',label:'居中标题'},{value:'brand',label:'品牌介绍'},{value:'search',label:'品牌搜索'},{value:'location',label:'位置入口'}] as const
function set<K extends keyof DecorationHeader>(key:K,value:DecorationHeader[K]){if(!props.disabled)page.value.header={...header.value,[key]:value}}
function show(){selected.value=header.value.mode;open.value=true}
function confirm(){set('mode',selected.value);open.value=false}
</script>
<template><section class="header-settings"><label class="header-toggle"><span>页面标题栏</span><USwitch :model-value="page.showHeader===true" :disabled="disabled" aria-label="显示页面标题栏" @update:model-value="page.showHeader=$event"/></label><template v-if="page.showHeader"><button type="button" class="header-style-trigger" :disabled="disabled" @click="show"><span>风格选择</span><b>{{styles.find(s=>s.value===header.mode)?.label}}</b><UIcon name="i-lucide-chevron-right"/></button><div v-if="header.mode==='title'" class="header-align"><span>对齐方式</span><div><button v-for="entry in [{value:'left',label:'居左'},{value:'center',label:'居中'}] as const" :key="entry.value" type="button" :aria-pressed="header.align===entry.value" :disabled="disabled" @click="set('align',entry.value)">{{entry.label}}</button></div></div><ImageSelectTile v-if="['brand','search'].includes(header.mode)" :src="header.imageId?imageUrl(header.imageId):null" label="品牌图片" :removable="!!header.imageId" :disabled="disabled" @select="picker=true" @remove="set('imageId',null)"/><UFormField v-if="['brand','search'].includes(header.mode)" label="品牌名称"><ConsoleInput :model-value="header.brandName" :maxlength="30" :disabled="disabled" placeholder="例如：我的站点" @update:model-value="set('brandName',String($event))"/></UFormField><UFormField v-if="header.mode!=='title'" :label="header.mode==='brand'?'品牌说明':header.mode==='search'?'搜索提示':'位置文字'"><ConsoleInput :model-value="header.text" :maxlength="30" :disabled="disabled" @update:model-value="set('text',String($event))"/></UFormField><UFormField v-if="header.mode!=='title'" :label="header.mode==='location'?'位置跳转':'品牌跳转'"><ConsolePagePathPicker :model-value="header.target" :options="routes" allow-empty :disabled="disabled" @update:model-value="set('target',$event)"/></UFormField><label v-if="header.mode==='search'" class="header-toggle"><span>搜索本页列表</span><USwitch :model-value="!!header.searchInput" :disabled="disabled" @update:model-value="set('searchInput',$event)"/></label><UFormField v-if="header.mode==='search'&&!header.searchInput" label="搜索跳转"><ConsolePagePathPicker :model-value="header.searchTarget" :options="routes" allow-empty :disabled="disabled" @update:model-value="set('searchTarget',$event)"/></UFormField><UFormField label="标题栏介绍"><ConsoleInput :model-value="header.subtitle||''" :maxlength="60" :disabled="disabled" @update:model-value="set('subtitle',String($event))"/></UFormField><DecorationColorField :model-value="header.background" label="背景颜色" :disabled="disabled" @update:model-value="set('background',$event)"/><DecorationColorField :model-value="header.color" label="文字颜色" :disabled="disabled" @update:model-value="set('color',$event)"/></template><ConsoleDialog v-model:open="open" title="标题栏风格" size="content"><template #body><div class="header-style-grid"><div v-for="style in styles" :key="style.value" role="button" tabindex="0" @keydown.enter="selected=style.value" @keydown.space.prevent="selected=style.value" :aria-pressed="selected===style.value" @click="selected=style.value"><div class="header-style-sample"><DecorationHeaderPreview :page="{...page,title:style.value==='title'?'页面标题':'品牌名称',header:{...header,brandName:'品牌名称',mode:style.value,imageId:null,text:style.value==='brand'?'品牌说明':style.value==='search'?'搜索关键词':'选择位置'}}" :image-url="imageUrl" editable/></div><span>{{style.label}}</span></div></div></template><template #footer><ConsoleFormActions><UButton color="neutral" variant="outline" @click="open=false">取消</UButton><UButton :disabled="disabled" @click="confirm">确定</UButton></ConsoleFormActions></template></ConsoleDialog><MaterialPicker v-model:open="picker" :endpoint="materialEndpoint" portal="tenant" purpose="library" @select="set('imageId',$event.id)"/></section></template>
<style scoped>
.header-settings{display:grid;gap:18px;border-top:1px solid var(--ui-border);border-bottom:1px solid var(--ui-border);padding:20px 0}.header-toggle,.header-style-trigger,.header-align{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px}.header-toggle>span{font-weight:500}.header-style-trigger b{margin-left:auto;color:var(--ui-primary);font-weight:400}.header-align>div{display:flex;border:1px solid var(--ui-border);border-radius:6px;padding:3px;gap:3px}.header-align button{padding:5px 12px;border-radius:4px}.header-align button[aria-pressed=true]{background:var(--ui-bg-elevated);color:var(--ui-primary)}.header-style-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.header-style-grid>[role=button]{min-width:0;overflow:hidden;border:1px solid var(--ui-border);border-radius:8px;padding:12px;background:var(--ui-bg-elevated)}.header-style-grid>[role=button][aria-pressed=true]{border-color:var(--ui-primary);box-shadow:0 0 0 1px var(--ui-primary)}.header-style-sample{container-type:inline-size;--diy-unit:calc(100cqw / 375);padding:16px 0;pointer-events:none}.header-style-grid>[role=button]>span{display:block;margin-top:10px;font-size:12px}@media(max-width:540px){.header-style-grid{grid-template-columns:1fr}}
</style>
